/**
 * 철근 항복강도 선택 — KS(MPa) / ACI(ksi) 양방향 연동
 * 기존 syncFyBoth() 대체
 */
const KS_OPTIONS  = [{ mpa: 400, ksi: 58.01 }, { mpa: 500, ksi: 72.52 }, { mpa: 600, ksi: 87.02 }]
const ACI_OPTIONS = [{ ksi: 60, mpa: 413.7 }, { ksi: 75, mpa: 517.1 }, { ksi: 80, mpa: 551.6 }]

const MPA_TO_KSI = 0.145038

/**
 * @param {object} p
 * @param {number}   p.fy_mpa       현재 MPa 값
 * @param {function} p.onChange     (fy_mpa: number) => void
 * @param {'ks'|'aci'} p.primary   어느 쪽 드롭다운을 왼쪽에 표시할지
 */
export default function FySelect({ fy_mpa, onChange, primary = 'ks' }) {
  const ksMatch  = KS_OPTIONS.find(o => o.mpa === fy_mpa)
  const aciMatch = ACI_OPTIONS.find(o => Math.abs(o.mpa - fy_mpa) < 1)

  // KS 선택값: 일치하는 옵션이 없으면 sentinel '_custom' 사용
  // → 다른 옵션 클릭 시 반드시 onChange가 발화됨
  const ksValue  = ksMatch  ? fy_mpa : '_custom'
  const aciValue = aciMatch ? aciMatch.ksi : '_custom'

  return (
    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 16 }}>
      {/* KS (MPa) */}
      <div>
        <label style={{ display: 'block', fontSize: 11, color: 'var(--tx-secondary)', marginBottom: 3 }}>
          🇰🇷 KS (MPa)
        </label>
        <select value={ksValue} onChange={e => { if (e.target.value !== '_custom') onChange(Number(e.target.value)) }} style={selectStyle}>
          {!ksMatch && <option value="_custom" disabled>{fy_mpa.toFixed(1)} MPa</option>}
          {KS_OPTIONS.map(o => (
            <option key={o.mpa} value={o.mpa}>{o.mpa} MPa</option>
          ))}
        </select>
      </div>

      {/* ACI (ksi) */}
      <div>
        <label style={{ display: 'block', fontSize: 11, color: 'var(--tx-secondary)', marginBottom: 3 }}>
          🇺🇸 ACI (ksi)
        </label>
        <select value={aciValue} onChange={e => { const opt = ACI_OPTIONS.find(o => o.ksi === Number(e.target.value)); if (opt) onChange(opt.mpa) }} style={selectStyle}>
          {!aciMatch && <option value="_custom" disabled>{(fy_mpa * MPA_TO_KSI).toFixed(2)} ksi</option>}
          {ACI_OPTIONS.map(o => (
            <option key={o.ksi} value={o.ksi}>{o.ksi} ksi</option>
          ))}
        </select>
      </div>
    </div>
  )
}

const selectStyle = {
  background: 'var(--bg-input)',
  border: '1px solid var(--bd-subtle)',
  borderRadius: 6,
  color: 'var(--tx-primary)',
  padding: '6px 8px',
  width: '100%',
  fontSize: 13,
}
