/**
 * 철근 간격 목록 렌더링 — 슬래브/벽체용
 */
export default function RebarSpacingList({ items, unit = 'mm' }) {
  // items: [{ name, spacing }]  or [{ name, s_l, s_t }] for wall
  if (!items?.length) return null

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
      {items.map(item => (
        <div
          key={item.name}
          style={{
            background: 'var(--bg-inset)',
            borderRadius: 6,
            padding: '6px 12px',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}
        >
          <span style={{ color: 'var(--tx-secondary)', fontSize: 12, fontWeight: 600 }}>
            {item.name}
          </span>
          <span style={{ fontWeight: 700, color: 'var(--val-pos)', fontSize: 13 }}>
            {item.s_l != null
              ? `${item.name}@${item.s_l.toFixed(unit === 'mm' ? 0 : 2)}(V) | ${item.name}@${item.s_t.toFixed(unit === 'mm' ? 0 : 2)}(H)`
              : `${item.name}@${item.spacing?.toFixed(unit === 'mm' ? 0 : 2)}${unit === 'in' ? '"' : ''}`
            }
          </span>
        </div>
      ))}
    </div>
  )
}
